javascript:
frappe.query_reports["Monthly Attendance Timesheet"] = {
	filters: [
		{
			fieldname: "from_date",
			label: "من تاريخ",
			fieldtype: "Date",
			default: frappe.datetime.month_start(),
			reqd: 1
		},
		{
			fieldname: "to_date",
			label: "إلى تاريخ",
			fieldtype: "Date",
			default: frappe.datetime.month_end(),
			reqd: 1
		},
		{
			fieldname: "employee",
			label: "الموظف",
			fieldtype: "Link",
			options: "Employee"
		},
		{
			fieldname: "department",
			label: "المديرية",
			fieldtype: "Link",
			options: "Department"
		}
	],

	onload: function(report) {
		report.datatable_options = {
			freezeColumns: 2
		};

		const style_id = "attendance-style-system";

		if (!document.getElementById(style_id)) {
			const style = document.createElement("style");
			style.id = style_id;
			style.innerHTML = `
				.compact-day {
					display: inline-flex;
					align-items: center;
					justify-content: center;
					gap: 6px;
					font-size: 12px;
					white-space: nowrap;
					line-height: 1.1;
					width: 100%;
				}

				.compact-hours,
				.badge-leave,
				.badge-absent,
				.badge-weekend {
					display: inline-flex;
					align-items: center;
					justify-content: center;
					width: 58px;
					min-width: 58px;
					height: 24px;
					padding: 0 6px;
					border-radius: 6px;
					font-weight: 700;
					font-size: 12px;
					box-sizing: border-box;
					text-align: center;
				}

				.compact-hours {
					background: #edf5ef;
					border: 1px solid #cfe0d3;
					color: #1f4d35;
				}

				.compact-time {
					font-size: 11px;
					color: #4b5563;
					direction: ltr;
					unicode-bidi: plaintext;
				}

				.badge-leave {
					background: #f6edb3;
					border: 1px solid #dbc96a;
					color: #6b5a00;
				}

				.badge-absent {
					background: #f7d7db;
					border: 1px solid #d7a3ab;
					color: #7a1020;
				}

				.badge-weekend {
					background: #ececec;
					border: 1px solid #d3d3d3;
					color: #5b5b5b;
				}

				.summary-box {
					display: flex;
					align-items: center;
					justify-content: center;
					width: 100%;
					min-height: 32px;
					padding: 4px 8px;
					border-radius: 4px;
					font-weight: 800;
					font-size: 13px;
					box-sizing: border-box;
					text-align: center;
					border: 1px solid transparent;
				}

				.summary-actual-work {
					background: #14532d;
					color: #ffffff;
					border-color: #0f3f22;
				}

				.summary-leave-hours {
					background: #c9b200;
					color: #1f1f1f;
					border-color: #a89300;
				}

				.summary-work-with-leave {
					background: #1f6a3a;
					color: #ffffff;
					border-color: #16522c;
				}

				.summary-approved-hours {
					background: #9a5b2a;
					color: #ffffff;
					border-color: #7f4a20;
				}

				.summary-unjustified {
					background: #6b0f1a;
					color: #ffffff;
					border-color: #4f0b14;
				}
			`;
			document.head.appendChild(style);
		}
	},

	formatter: function(value, row, column, data, default_formatter) {
		if (!column || !column.fieldname) {
			return default_formatter(value, row, column, data);
		}

		if (["employee", "employee_name", "department"].includes(column.fieldname)) {
			return '<div style="font-weight:600;">' + (value || "") + '</div>';
		}

		if (column.fieldname === "actual_work_hours") {
			return '<div class="summary-box summary-actual-work">' + (value || 0) + '</div>';
		}

		if (column.fieldname === "leave_hours") {
			return '<div class="summary-box summary-leave-hours">' + (value || 0) + '</div>';
		}

		if (column.fieldname === "work_with_leave") {
			return '<div class="summary-box summary-work-with-leave">' + (value || 0) + '</div>';
		}

		if (column.fieldname === "approved_hours") {
			return '<div class="summary-box summary-approved-hours">' + (value || 0) + '</div>';
		}

		if (column.fieldname === "unjustified_hours") {
			return '<div class="summary-box summary-unjustified">' + (value || 0) + '</div>';
		}

		if (column.fieldname.startsWith("d_")) {
			const raw = value || "ABSENT|||";
			const parts = String(raw).split("|");

			const status = parts[0] || "ABSENT";
			const hours = parts[1] || "";
			const inTime = parts[2] || "";
			const outTime = parts[3] || "";

			if (status === "LEAVE") {
				return '<span class="badge-leave">إجازة</span>';
			}

			if (status === "WEEKEND") {
				return '<span class="badge-weekend">عطلة</span>';
			}

			if (status === "ABSENT") {
				return '<span class="badge-absent">غياب</span>';
			}

			return (
				'<div class="compact-day">' +
					'<span class="compact-hours">' + hours + '</span>' +
					'<span class="compact-time">' + (inTime || "--") + '→' + (outTime || "--") + '</span>' +
				'</div>'
			);
		}

		return default_formatter(value, row, column, data);
	}
};

report_script:
filters = filters or {}

from_date = filters.get("from_date") or frappe.utils.get_first_day(frappe.utils.today())
to_date = filters.get("to_date") or frappe.utils.get_last_day(frappe.utils.today())
employee = filters.get("employee")
department = filters.get("department")

if from_date > to_date:
    frappe.throw("قيمة from_date يجب أن تكون أصغر أو تساوي to_date")


date_list = []
current_date = frappe.utils.getdate(from_date)
end_date = frappe.utils.getdate(to_date)

while current_date <= end_date:
    date_list.append(str(current_date))
    current_date = frappe.utils.add_days(current_date, 1)

columns = [
    {
        "label": "الرقم الوظيفي",
        "fieldname": "employee",
        "fieldtype": "Data",
        "width": 140
    },
    {
        "label": "اسم الموظف",
        "fieldname": "employee_name",
        "fieldtype": "Data",
        "width": 220
    },
    {
        "label": "المديرية",
        "fieldname": "department",
        "fieldtype": "Data",
        "width": 220
    }
]

month_map = {
    "01": "Jan",
    "02": "Feb",
    "03": "Mar",
    "04": "Apr",
    "05": "May",
    "06": "Jun",
    "07": "Jul",
    "08": "Aug",
    "09": "Sep",
    "10": "Oct",
    "11": "Nov",
    "12": "Dec"
}

date_field_map = {}

for dt in date_list:
    safe_dt = "d_" + dt.replace("-", "_")
    date_field_map[dt] = safe_dt

    day_part = dt[8:10]
    month_part = dt[5:7]
    year_part = dt[0:4]

    label_date = day_part + " " + month_map.get(month_part, month_part) + " " + year_part

    columns.append({
        "label": label_date,
        "fieldname": safe_dt,
        "fieldtype": "Data",
        "width": 140
    })

columns.extend([
    {
        "label": "عدد ساعات العمل الفعلية",
        "fieldname": "actual_work_hours",
        "fieldtype": "Float",
        "width": 170
    },
    {
        "label": "عدد ساعات الاجازات المبررة",
        "fieldname": "leave_hours",
        "fieldtype": "Float",
        "width": 170
    },
    {
        "label": "عدد الساعات الفعلي مع الإجازات",
        "fieldname": "work_with_leave",
        "fieldtype": "Float",
        "width": 180
    },
    {
        "label": "الساعات المعتمدة لهذا الشهر",
        "fieldname": "approved_hours",
        "fieldtype": "Float",
        "width": 180
    },
    {
        "label": "غير المبررة",
        "fieldname": "unjustified_hours",
        "fieldtype": "Float",
        "width": 150
    }
])

attendance_filters = {
    "attendance_date": ["between", [from_date, to_date]]
}

if employee:
    attendance_filters["employee"] = employee

if department:
    attendance_filters["department"] = department

records = frappe.get_all(
    "Attendance",
    filters=attendance_filters,
    fields=[
        "employee",
        "employee_name",
        "department",
        "attendance_date",
        "status",
        "working_hours",
        "in_time",
        "out_time",
        "shift"
    ],
    order_by="employee asc, attendance_date asc"
)

employee_list = []
employee_seen = {}
employee_default_shift = {}

shift_names = []
shift_seen = {}

for row in records:
    if row.employee and row.employee not in employee_seen:
        employee_list.append(row.employee)
        employee_seen[row.employee] = 1

    if row.employee and row.shift and row.employee not in employee_default_shift:
        employee_default_shift[row.employee] = row.shift

    if row.shift and row.shift not in shift_seen:
        shift_names.append(row.shift)
        shift_seen[row.shift] = 1

assignment_filters = {
    "start_date": ["<=", to_date]
}

if employee_list:
    assignment_filters["employee"] = ["in", employee_list]

if employee:
    assignment_filters["employee"] = employee

shift_assignments = frappe.get_all(
    "Shift Assignment",
    filters=assignment_filters,
    fields=[
        "employee",
        "shift_type",
        "start_date",
        "end_date"
    ],
    order_by="employee asc, start_date asc"
)

employee_date_shift_map = {}

for sa in shift_assignments:
    if not sa.employee or not sa.shift_type or not sa.start_date:
        continue

    assignment_start = frappe.utils.getdate(sa.start_date)
    assignment_end = frappe.utils.getdate(sa.end_date) if sa.end_date else frappe.utils.getdate(to_date)
    report_start = frappe.utils.getdate(from_date)
    report_end = frappe.utils.getdate(to_date)

    if assignment_start < report_start:
        assignment_start = report_start

    if assignment_end > report_end:
        assignment_end = report_end

    if assignment_start > assignment_end:
        continue

    if sa.shift_type not in shift_seen:
        shift_names.append(sa.shift_type)
        shift_seen[sa.shift_type] = 1

    d = assignment_start
    while d <= assignment_end:
        employee_date_shift_map[sa.employee + "||" + str(d)] = sa.shift_type
        d = frappe.utils.add_days(d, 1)

shift_map = {}
holiday_list_names = []
holiday_list_seen = {}

if shift_names:
    shift_rows = frappe.get_all(
        "Shift Type",
        filters={"name": ["in", shift_names]},
        fields=[
            "name",
            "start_time",
            "end_time",
            "early_exit_grace_period",
            "holiday_list"
        ]
    )

    for shift_row in shift_rows:
        shift_map[shift_row.name] = shift_row

        if shift_row.holiday_list and shift_row.holiday_list not in holiday_list_seen:
            holiday_list_names.append(shift_row.holiday_list)
            holiday_list_seen[shift_row.holiday_list] = 1

holiday_map = {}

if holiday_list_names:
    holiday_rows = frappe.get_all(
        "Holiday",
        filters={
            "parent": ["in", holiday_list_names],
            "holiday_date": ["between", [from_date, to_date]]
        },
        fields=[
            "parent",
            "holiday_date"
        ]
    )

    for hr in holiday_rows:
        holiday_map[hr.parent + "||" + str(hr.holiday_date)] = 1

employees_map = {}

for row in records:
    emp = row.employee

    if emp not in employees_map:
        base_row = {
            "employee": row.employee or "",
            "employee_name": row.employee_name or "",
            "department": row.department or ""
        }

        for dt in date_list:
            safe_dt = date_field_map[dt]

            shift_name = employee_date_shift_map.get(emp + "||" + dt)
            if not shift_name:
                shift_name = employee_default_shift.get(emp)

            is_holiday = 0

            if shift_name and shift_name in shift_map:
                holiday_list_name = shift_map[shift_name].holiday_list
                if holiday_list_name and holiday_map.get(holiday_list_name + "||" + dt):
                    is_holiday = 1

            if not is_holiday:
                weekday = frappe.utils.getdate(dt).weekday()
                if weekday in [4, 5]:
                    is_holiday = 1

            if is_holiday:
                base_row[safe_dt] = "WEEKEND|||"
            else:
                base_row[safe_dt] = "ABSENT|||"

        employees_map[emp] = base_row

    day_key = str(row.attendance_date)
    safe_day_key = date_field_map.get(day_key)

    if not safe_day_key:
        continue

    status_value = row.status or ""

    if status_value == "Absent":
        shift_name = employee_date_shift_map.get(emp + "||" + day_key)
        if not shift_name:
            shift_name = employee_default_shift.get(emp)

        is_holiday = 0

        if shift_name and shift_name in shift_map:
            holiday_list_name = shift_map[shift_name].holiday_list
            if holiday_list_name and holiday_map.get(holiday_list_name + "||" + day_key):
                is_holiday = 1

        if not is_holiday:
            weekday = frappe.utils.getdate(day_key).weekday()
            if weekday in [4, 5]:
                is_holiday = 1

        if is_holiday:
            employees_map[emp][safe_day_key] = "WEEKEND|||"
        else:
            employees_map[emp][safe_day_key] = "ABSENT|||"

    elif status_value == "On Leave":
        shift_name = employee_date_shift_map.get(emp + "||" + day_key)
        if not shift_name:
            shift_name = employee_default_shift.get(emp)

        is_holiday = 0

        if shift_name and shift_name in shift_map:
            holiday_list_name = shift_map[shift_name].holiday_list
            if holiday_list_name and holiday_map.get(holiday_list_name + "||" + day_key):
                is_holiday = 1

        if not is_holiday:
            weekday = frappe.utils.getdate(day_key).weekday()
            if weekday in [4, 5]:
                is_holiday = 1

        leave_day_hours = 0

        if not is_holiday and shift_name and shift_name in shift_map:
            shift_doc = shift_map[shift_name]

            start_txt = str(shift_doc.start_time or "")
            end_txt = str(shift_doc.end_time or "")

            if " " in start_txt:
                start_txt = start_txt.split(" ")[-1]
            if " " in end_txt:
                end_txt = end_txt.split(" ")[-1]

            sp = start_txt.split(":")
            ep = end_txt.split(":")

            sh = int(sp[0]) if len(sp) > 0 and sp[0] else 0
            sm = int(sp[1]) if len(sp) > 1 and sp[1] else 0
            ss = int(sp[2]) if len(sp) > 2 and sp[2] else 0

            eh = int(ep[0]) if len(ep) > 0 and ep[0] else 0
            em = int(ep[1]) if len(ep) > 1 and ep[1] else 0
            es = int(ep[2]) if len(ep) > 2 and ep[2] else 0

            start_minutes = (sh * 60) + sm
            end_minutes = (eh * 60) + em

            if ss >= 30:
                start_minutes = start_minutes + 1

            if es >= 30:
                end_minutes = end_minutes + 1

            if end_minutes < start_minutes:
                end_minutes = end_minutes + (24 * 60)

            grace_minutes = int(shift_doc.early_exit_grace_period or 0)
            total_minutes = (end_minutes - start_minutes) + grace_minutes
            leave_day_hours = round(float(total_minutes or 0) / 60.0, 2)

        employees_map[emp][safe_day_key] = "LEAVE|" + str(leave_day_hours) + "||"

    elif status_value == "Work From Home":
        total_hours = 0

        if row.shift and row.shift in shift_map:
            shift_doc = shift_map[row.shift]

            start_txt = str(shift_doc.start_time or "")
            end_txt = str(shift_doc.end_time or "")

            if " " in start_txt:
                start_txt = start_txt.split(" ")[-1]
            if " " in end_txt:
                end_txt = end_txt.split(" ")[-1]

            sp = start_txt.split(":")
            ep = end_txt.split(":")

            sh = int(sp[0]) if len(sp) > 0 and sp[0] else 0
            sm = int(sp[1]) if len(sp) > 1 and sp[1] else 0
            ss = int(sp[2]) if len(sp) > 2 and sp[2] else 0

            eh = int(ep[0]) if len(ep) > 0 and ep[0] else 0
            em = int(ep[1]) if len(ep) > 1 and ep[1] else 0
            es = int(ep[2]) if len(ep) > 2 and ep[2] else 0

            start_minutes = (sh * 60) + sm
            end_minutes = (eh * 60) + em

            if ss >= 30:
                start_minutes = start_minutes + 1

            if es >= 30:
                end_minutes = end_minutes + 1

            if end_minutes < start_minutes:
                end_minutes = end_minutes + (24 * 60)

            grace_minutes = int(shift_doc.early_exit_grace_period or 0)
            total_minutes = (end_minutes - start_minutes) + grace_minutes
            total_hours = round(float(total_minutes or 0) / 60.0, 2)
        else:
            shift_name = employee_date_shift_map.get(emp + "||" + day_key)
            if not shift_name:
                shift_name = employee_default_shift.get(emp)

            if shift_name and shift_name in shift_map:
                shift_doc = shift_map[shift_name]

                start_txt = str(shift_doc.start_time or "")
                end_txt = str(shift_doc.end_time or "")

                if " " in start_txt:
                    start_txt = start_txt.split(" ")[-1]
                if " " in end_txt:
                    end_txt = end_txt.split(" ")[-1]

                sp = start_txt.split(":")
                ep = end_txt.split(":")

                sh = int(sp[0]) if len(sp) > 0 and sp[0] else 0
                sm = int(sp[1]) if len(sp) > 1 and sp[1] else 0
                ss = int(sp[2]) if len(sp) > 2 and sp[2] else 0

                eh = int(ep[0]) if len(ep) > 0 and ep[0] else 0
                em = int(ep[1]) if len(ep) > 1 and ep[1] else 0
                es = int(ep[2]) if len(ep) > 2 and ep[2] else 0

                start_minutes = (sh * 60) + sm
                end_minutes = (eh * 60) + em

                if ss >= 30:
                    start_minutes = start_minutes + 1

                if es >= 30:
                    end_minutes = end_minutes + 1

                if end_minutes < start_minutes:
                    end_minutes = end_minutes + (24 * 60)

                grace_minutes = int(shift_doc.early_exit_grace_period or 0)
                total_minutes = (end_minutes - start_minutes) + grace_minutes
                total_hours = round(float(total_minutes or 0) / 60.0, 2)

        employees_map[emp][safe_day_key] = "WFH|" + str(total_hours) + "||"

    elif status_value == "Present":
        in_time = frappe.utils.format_time(row.in_time, "HH:mm") if row.in_time else ""
        out_time = frappe.utils.format_time(row.out_time, "HH:mm") if row.out_time else ""

        if in_time and out_time:
            hours = str(round(float(row.working_hours or 0), 2))
            employees_map[emp][safe_day_key] = "PRESENT|" + hours + "|" + in_time + "|" + out_time
        else:
            shift_name = employee_date_shift_map.get(emp + "||" + day_key)
            if not shift_name:
                shift_name = employee_default_shift.get(emp)

            is_holiday = 0

            if shift_name and shift_name in shift_map:
                holiday_list_name = shift_map[shift_name].holiday_list
                if holiday_list_name and holiday_map.get(holiday_list_name + "||" + day_key):
                    is_holiday = 1

            if not is_holiday:
                weekday = frappe.utils.getdate(day_key).weekday()
                if weekday in [4, 5]:
                    is_holiday = 1

            if is_holiday:
                employees_map[emp][safe_day_key] = "WEEKEND|||"
            else:
                employees_map[emp][safe_day_key] = "ABSENT|||"

    else:
        in_time = frappe.utils.format_time(row.in_time, "HH:mm") if row.in_time else ""
        out_time = frappe.utils.format_time(row.out_time, "HH:mm") if row.out_time else ""

        if in_time and out_time:
            hours = str(round(float(row.working_hours or 0), 2))
            employees_map[emp][safe_day_key] = "PRESENT|" + hours + "|" + in_time + "|" + out_time
        else:
            shift_name = employee_date_shift_map.get(emp + "||" + day_key)
            if not shift_name:
                shift_name = employee_default_shift.get(emp)

            is_holiday = 0

            if shift_name and shift_name in shift_map:
                holiday_list_name = shift_map[shift_name].holiday_list
                if holiday_list_name and holiday_map.get(holiday_list_name + "||" + day_key):
                    is_holiday = 1

            if not is_holiday:
                weekday = frappe.utils.getdate(day_key).weekday()
                if weekday in [4, 5]:
                    is_holiday = 1

            if is_holiday:
                employees_map[emp][safe_day_key] = "WEEKEND|||"
            else:
                employees_map[emp][safe_day_key] = "ABSENT|||"

result = []

for emp in employees_map:
    row = employees_map[emp]

    actual_work_hours = 0.0
    leave_hours = 0.0
    approved_hours = 0.0

    for dt in date_list:
        cell = row.get(date_field_map[dt], "ABSENT|||")
        parts = str(cell).split("|")

        status = parts[0] if len(parts) > 0 else ""
        cell_hours = float(parts[1]) if len(parts) > 1 and parts[1] else 0.0

        shift_name = employee_date_shift_map.get(emp + "||" + dt)
        if not shift_name:
            shift_name = employee_default_shift.get(emp)

        is_holiday = 0

        if shift_name and shift_name in shift_map:
            holiday_list_name = shift_map[shift_name].holiday_list
            if holiday_list_name and holiday_map.get(holiday_list_name + "||" + dt):
                is_holiday = 1

        if not is_holiday:
            weekday = frappe.utils.getdate(dt).weekday()
            if weekday in [4, 5]:
                is_holiday = 1

        expected_hours = 0.0

        if not is_holiday and shift_name and shift_name in shift_map:
            shift_doc = shift_map[shift_name]

            start_txt = str(shift_doc.start_time or "")
            end_txt = str(shift_doc.end_time or "")

            if " " in start_txt:
                start_txt = start_txt.split(" ")[-1]
            if " " in end_txt:
                end_txt = end_txt.split(" ")[-1]

            sp = start_txt.split(":")
            ep = end_txt.split(":")

            sh = int(sp[0]) if len(sp) > 0 and sp[0] else 0
            sm = int(sp[1]) if len(sp) > 1 and sp[1] else 0
            ss = int(sp[2]) if len(sp) > 2 and sp[2] else 0

            eh = int(ep[0]) if len(ep) > 0 and ep[0] else 0
            em = int(ep[1]) if len(ep) > 1 and ep[1] else 0
            es = int(ep[2]) if len(ep) > 2 and ep[2] else 0

            start_minutes = (sh * 60) + sm
            end_minutes = (eh * 60) + em

            if ss >= 30:
                start_minutes = start_minutes + 1

            if es >= 30:
                end_minutes = end_minutes + 1

            if end_minutes < start_minutes:
                end_minutes = end_minutes + (24 * 60)

            grace_minutes = int(shift_doc.early_exit_grace_period or 0)
            total_minutes = (end_minutes - start_minutes) + grace_minutes
            expected_hours = round(float(total_minutes or 0) / 60.0, 2)

        if expected_hours > 0:
            approved_hours = approved_hours + expected_hours

        if status == "PRESENT":
            actual_work_hours = actual_work_hours + cell_hours
        elif status == "WFH":
            actual_work_hours = actual_work_hours + cell_hours
        elif status == "LEAVE":
            leave_hours = leave_hours + expected_hours

    work_with_leave = actual_work_hours + leave_hours
    unjustified_hours = approved_hours - work_with_leave

    if unjustified_hours < 0:
        unjustified_hours = 0

    row["actual_work_hours"] = round(actual_work_hours, 2)
    row["leave_hours"] = round(leave_hours, 2)
    row["work_with_leave"] = round(work_with_leave, 2)
    row["approved_hours"] = round(approved_hours, 2)
    row["unjustified_hours"] = round(unjustified_hours, 2)

    result.append(row)

data = columns, result
